f:[['Name','Possibly "friendship"; meaning uncertain'],['Era','Time of the judges, about 1100 BC'],['Family','Husband Mahlon (died); mother-in-law Naomi; husband Boaz; son Obed'],['Places','Moab and Bethlehem'],['Main passages','The book of Ruth; Matthew 1:5']],
st:[['Naomi\'s family flees famine to Moab; husband and sons die','Ruth 1:1-5'],['Ruth refuses to leave Naomi: "Your people shall be my people, and your God my God"','Ruth 1:6-18'],['Arrives in Bethlehem at the barley harvest','Ruth 1:19-22'],['Gleans in Boaz\'s field and finds favour','Ruth 2'],['Naomi\'s plan; Ruth at the threshing floor asks Boaz to redeem','Ruth 3'],['Boaz settles the matter with the nearer kinsman at the gate','Ruth 4:1-8'],['Marries Boaz; Obed is born','Ruth 4:9-17'],['The line of David','Ruth 4:17-22']],
